#include <bits/stdc++.h>
using namespace std;

struct Tree {
    int n;
    vector<vector<int>> adj;
    vector<int> parent;
    vector<int> val;
    vector<bool> is_leaf;
    int root;
};

Tree* build_tree(int n, int edges[][2], int num_edges) {
    Tree* t = new Tree;
    t->n = n;
    t->adj.resize(n);
    t->parent.resize(n);
    t->val.resize(n);
    t->is_leaf.resize(n);
    t->root = 1;

    for (int i = 0; i < num_edges; ++i) {
        int u = edges[i][0];
        int v = edges[i][1];
        t->adj[u-1].push_back(v-1);
        t->adj[v-1].push_back(u-1);
    }

    // BFS to build parent and is_leaf
    queue<int> q;
    q.push(t->root);
    t->is_leaf[t->root] = false;
    while (!q.empty()) {
        int u = q.front();
        q.pop();
        for (int v : t->adj[u]) {
            if (v != t->parent[u]) {
                t->parent[v] = u;
                if (t->is_leaf[v]) {
                    t->is_leaf[u] = true;
                }
                if (t->is_leaf[u]) {
                    t->is_leaf[v] = false;
                }
                q.push(v);
            }
        }
    }

    return t;
}

int main() {
    int t;
    cin >> t;
    while (t--) {
        int n;
        cin >> n;
        int edges[100000][2];
        int num_edges = n-1;
        for (int i = 0; i < num_edges; ++i) {
            int u, v;
            cin >> u >> v;
            edges[i][0] = u;
            edges[i][1] = v;
        }
        Tree* t = build_tree(n, edges, num_edges);
        string s;
        cin >> s;

        // Compute val
        for (int i = 0; i < n; ++i) {
            if (s[i] == '?') {
                if (i == 0) {
                    t->val[i] = 0;
                } else {
                    t->val[i] = 1 - t->val[t->parent[i]];
                }
            } else {
                t->val[i] = s[i] == '1' ? 1 : 0;
            }
        }

        // Compute score
        int score = 0;
        for (int i = 1; i <= n; ++i) {
            if (t->is_leaf[i]) {
                int sum = 0;
                int prev = t->val[0];
                for (int j = 1; j < i; ++j) {
                    if (t->val[j] != prev) {
                        if (prev == 0) {
                            sum++;
                        } else {
                            sum--;
                        }
                        prev = t->val[j];
                    }
                }
                if (sum != 0) {
                    score++;
                }
            }
        }

        cout << score << "\n";
    }
    return 0;
}
